#!/usr/bin/env python3
from pathlib import Path
import zlib,base64
NEXT_JS='' # compressed hf33-next-version.js
PRE=''
MEM=''
BUILD=''
def inflate(v): return zlib.decompress(base64.b64decode(v)).decode('utf-8')
Path('dist/assets/hf33-next-version.js').write_text(inflate(NEXT_JS),encoding='utf-8')
Path('dist/assets/hf33-explorer-preload.js').write_text(inflate(PRE),encoding='utf-8')
Path('dist/assets/member-public.js').write_text(inflate(MEM),encoding='utf-8')
exec(compile(inflate(BUILD),'hf33-build-core.py','exec'))
